ALTER TABLE beacon."agency_memberships" ADD CONSTRAINT "agency_memberships_tenant_id_organizations_id_fk" FOREIGN KEY ("tenant_id") REFERENCES beacon."organizations" ("id");

ALTER TABLE beacon."agency_memberships" ADD CONSTRAINT "agency_memberships_tenant_id_user_id_users_tenant_id_id_fk" FOREIGN KEY ("tenant_id", "user_id") REFERENCES beacon."users" ("tenant_id", "id");

CREATE UNIQUE INDEX "agency_membership_user" ON beacon."agency_memberships" ("tenant_id", "user_id");

ALTER TABLE beacon."agency_memberships" ENABLE ROW LEVEL SECURITY;

ALTER TABLE beacon."agency_memberships" FORCE ROW LEVEL SECURITY;

CREATE POLICY "founder_management" ON beacon."agency_memberships" FOR ALL TO beacon_founder USING ("beacon"."agency_memberships"."tenant_id"=NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK ("beacon"."agency_memberships"."tenant_id"=NULLIF(current_setting('app.tenant_id', true), '')::uuid);

CREATE POLICY "own_grant" ON beacon."agency_memberships" FOR SELECT TO beacon_app USING ("beacon"."agency_memberships"."tenant_id"=NULLIF(current_setting('app.tenant_id', true), '')::uuid AND "beacon"."agency_memberships"."user_id"=NULLIF(current_setting('app.actor_id', true), '')::uuid);

GRANT SELECT ON beacon."agency_memberships" TO beacon_app;

GRANT SELECT, INSERT, UPDATE, DELETE ON beacon."agency_memberships" TO beacon_founder;

