ALTER TABLE beacon."agent_grants" ADD CONSTRAINT "agent_grants_tenant_id_organizations_id_fk" FOREIGN KEY ("tenant_id") REFERENCES beacon."organizations" ("id");

ALTER TABLE beacon."agent_grants" ADD CONSTRAINT "agent_grants_tenant_id_agent_id_agents_tenant_id_id_fk" FOREIGN KEY ("tenant_id", "agent_id") REFERENCES beacon."agents" ("tenant_id", "id");

CREATE UNIQUE INDEX "agent_grant_identity" ON beacon."agent_grants" ("tenant_id", "agent_id", "kind", "subject", "client_id");

ALTER TABLE beacon."agent_grants" ENABLE ROW LEVEL SECURITY;

ALTER TABLE beacon."agent_grants" FORCE ROW LEVEL SECURITY;

CREATE POLICY "founder_management" ON beacon."agent_grants" FOR ALL TO beacon_founder USING ("beacon"."agent_grants"."tenant_id"=NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK ("beacon"."agent_grants"."tenant_id"=NULLIF(current_setting('app.tenant_id', true), '')::uuid);

CREATE POLICY "own_grant" ON beacon."agent_grants" FOR SELECT TO beacon_app USING ("beacon"."agent_grants"."tenant_id"=NULLIF(current_setting('app.tenant_id', true), '')::uuid AND "beacon"."agent_grants"."agent_id"=NULLIF(current_setting('app.actor_id', true), '')::uuid);

GRANT SELECT ON beacon."agent_grants" TO beacon_app;

GRANT SELECT, INSERT, UPDATE, DELETE ON beacon."agent_grants" TO beacon_founder;

CREATE POLICY principal_organization ON beacon.organizations FOR SELECT TO beacon_app USING (id=NULLIF(current_setting('app.tenant_id',true),'')::uuid AND (EXISTS (SELECT 1 FROM beacon.agency_memberships m WHERE m.tenant_id=beacon.organizations.id AND m.user_id=NULLIF(current_setting('app.actor_id',true),'')::uuid AND m.status='active') OR EXISTS (SELECT 1 FROM beacon.agent_grants g WHERE g.tenant_id=beacon.organizations.id AND g.agent_id=NULLIF(current_setting('app.actor_id',true),'')::uuid AND g.status='active' AND g.expires_at>now())));

CREATE FUNCTION beacon.serialize_access_change() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE organization uuid; previous_organization uuid; following_organization uuid;
BEGIN
  IF TG_TABLE_NAME IN ('organizations','tenants') THEN
    IF TG_OP <> 'INSERT' THEN previous_organization := OLD.id; END IF;
    IF TG_OP <> 'DELETE' THEN following_organization := NEW.id; END IF;
  ELSE
    IF TG_OP <> 'INSERT' THEN previous_organization := OLD.tenant_id; END IF;
    IF TG_OP <> 'DELETE' THEN following_organization := NEW.tenant_id; END IF;
  END IF;
  FOR organization IN SELECT DISTINCT candidate FROM unnest(ARRAY[previous_organization,following_organization]) AS candidates(candidate) WHERE candidate IS NOT NULL ORDER BY candidate LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended('roaswell-access/' || organization::text, 0));
  END LOOP;
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $$;

CREATE TRIGGER serialize_access_change BEFORE INSERT OR UPDATE OR DELETE ON beacon."organizations" FOR EACH ROW EXECUTE FUNCTION beacon.serialize_access_change();

CREATE TRIGGER serialize_access_change BEFORE INSERT OR UPDATE OR DELETE ON beacon."memberships" FOR EACH ROW EXECUTE FUNCTION beacon.serialize_access_change();

CREATE TRIGGER serialize_access_change BEFORE INSERT OR UPDATE OR DELETE ON beacon."agency_memberships" FOR EACH ROW EXECUTE FUNCTION beacon.serialize_access_change();

CREATE TRIGGER serialize_access_change BEFORE INSERT OR UPDATE OR DELETE ON beacon."agent_grants" FOR EACH ROW EXECUTE FUNCTION beacon.serialize_access_change();

CREATE TRIGGER serialize_access_change BEFORE INSERT OR UPDATE OR DELETE ON beacon."agents" FOR EACH ROW EXECUTE FUNCTION beacon.serialize_access_change();

CREATE TRIGGER serialize_access_change BEFORE INSERT OR UPDATE OR DELETE ON beacon."users" FOR EACH ROW EXECUTE FUNCTION beacon.serialize_access_change();
